require("dotenv").config();
const mongoose = require("mongoose");
const Order = require("./models/newOrder.model");

const TARGET_INSTRUCTIONS = [
  "Delhivery manifest created",
  "LR & AWB generated by Delhivery",
];

(async () => {
  await mongoose.connect(process.env.MONGODB_URI);

  const order = await Order.findById("6a6b64875b6e8e40ac21e065");
  if (!order) {
    console.log("Order not found.");
    process.exit(1);
  }

  let fixed = 0;
  order.tracking.forEach((entry) => {
    if (TARGET_INSTRUCTIONS.includes(entry.Instructions) && entry.StatusDateTime) {
      const before = entry.StatusDateTime;
      entry.StatusDateTime = new Date(before.getTime() + 5.5 * 60 * 60 * 1000);
      console.log(`"${entry.Instructions}": ${before.toISOString()} -> ${entry.StatusDateTime.toISOString()}`);
      fixed++;
    }
  });

  await order.save();
  console.log(`Fixed ${fixed} tracking entries.`);
  await mongoose.disconnect();
  process.exit(0);
})().catch((err) => {
  console.error("ERROR:", err);
  process.exit(1);
});
